/*
 * Battlegrounds core types: the generated card table, tribes and keywords as bit sets, the Minion,
 * the Board (7) and the Hand (10), and the seeded Rng every Battlegrounds engine part shares.
 *
 * PURE C++ (standard library only, no core headers and no src/match) so it can be unit-tested headlessly, like
 * src/arena. The card table (HsBgCardData.inc) is generated by tools/battlegrounds/gen_bg_cpp.py: stats only, no
 * names or card text. A card INDEX is the row number in that table; it is stable only until the dataset changes, so
 * never store one: store the id (CardDef::id) and map it back with FindCard.
 *
 * Randomness: one Rng per game or combat, seeded, so the same seed and the same actions replay the same game. The Rng
 * does not use std::uniform_int_distribution (its output differs between standard libraries); Uniform is an
 * unbiased rejection sampler over mt19937 and gives the same numbers on every compiler.
 */

#ifndef MOD_HEARTHSTONE_HS_BG_TYPES_H
#define MOD_HEARTHSTONE_HS_BG_TYPES_H

#include <array>
#include <cstddef>
#include <cstdint>
#include <random>
#include <string>
#include <utility>
#include <vector>

namespace Hs
{
    namespace Bg
    {
        constexpr int kBoardMax = 7;      // minions on a board
        constexpr int kHandMax = 10;      // cards in a hand
        constexpr int kMinTier = 1;
        constexpr int kMaxTier = 6;       // tavern tiers; a pool minion has tier 1..6, a token counts as tier 1
        constexpr int kMinionCounters = 4;
        // counters[kCounterAvenge] is owned by the combat engine (Avenge progress, reset to 0 at the start of every
        // combat). counters[1..3] are free for effects (shop or combat); combat resets nothing else.
        constexpr int kCounterAvenge = 0;
        // The per-turn mark of Snail Cavalry (a spell was cast) and of Lava Lurker (Spellcraft spells made
        // permanent this turn). Both are reset at the owner's StartTurn.
        constexpr int kCounterOncePerTurn = 3;
        constexpr int kCounterSpellcraftPermanent = 3;
        // Frenzy (Roadboar, Bristleback Knight) counts the surviving-damage triggers of one combat.
        constexpr int kCounterFrenzy = 2;

        // Tribe bit set. kTribeAll (Nightmare Amalgam) counts as every tribe: use HasTribe, not a plain mask test.
        enum Tribe : uint32_t
        {
            kTribeBeast = 1u << 0,
            kTribeDemon = 1u << 1,
            kTribeDragon = 1u << 2,
            kTribeElemental = 1u << 3,
            kTribeMech = 1u << 4,
            kTribeMurloc = 1u << 5,
            kTribeNaga = 1u << 6,
            kTribePirate = 1u << 7,
            kTribeQuilboar = 1u << 8,
            kTribeAll = 1u << 9,
        };
        constexpr uint32_t kAllTribesMask = (1u << 10) - 1; // every Tribe bit including kTribeAll

        // Keyword bit set. A golden Windfury minion has kKwMegaWindfury instead of kKwWindfury (four attacks).
        enum Keyword : uint32_t
        {
            kKwTaunt = 1u << 0,
            kKwDivineShield = 1u << 1,
            kKwPoisonous = 1u << 2,
            kKwWindfury = 1u << 3,
            kKwReborn = 1u << 4,
            kKwMagnetic = 1u << 5,
            kKwMegaWindfury = 1u << 6,
            kKwStealth = 1u << 7,   // can't be attacked until it attacks (Theotar's Parasol)
            kKwVenomous = 1u << 8,  // Poisonous until it destroys a minion once (Mantid Queen, render data)
        };

        constexpr bool HasTribe(uint32_t tribes, uint32_t tribe) { return (tribes & (tribe | kTribeAll)) != 0; }
        // Attacks per turn in the attack order from the keyword set: 4 (Mega-Windfury), 2 (Windfury) or 1.
        constexpr int AttacksPerTurn(uint32_t keywords)
        {
            return (keywords & kKwMegaWindfury) ? 4 : ((keywords & kKwWindfury) ? 2 : 1);
        }

        // Spells are rows of the same table (CardRole::Spell). Their attack / health are 0 and their tier
        // is 0 (Gold Coin, Bananas) or the source minion's Tier (Spellcraft spells); FindCard finds them by id, the pool
        // queries never return them.
        enum class CardRole : uint8_t { Pool, Token, Spell };

        // One row of the generated table. Golden stats are the golden card's own (the data doubles the base card).
        struct CardDef
        {
            char const* id;
            uint32_t dbfId;
            int tier;
            int attack;
            int health;
            uint32_t tribes;
            uint32_t keywords;
            char const* goldenId;     // "" when the card has no golden version (the token Golden Monkey)
            uint32_t goldenDbfId;
            int goldenAttack;
            int goldenHealth;
            uint32_t goldenKeywords;
            bool slice15A;
            CardRole role;
        };

        // The table. CardAt requires 0 <= index < CardCount().
        int CardCount();
        CardDef const& CardAt(int index);
        // Index of a card by its normal id, or -1. FindCardAny also accepts a golden id (sets golden), -1 if unknown.
        int FindCard(std::string const& id);
        int FindCardAny(std::string const& id, bool& golden);

        // A hero row (HsBgHeroData.inc, generated). FindHero returns the table index, -1 if unknown. The power id
        // keys a HeroPowerDef (HsBgHeroes.h), which holds the cost. The armor is rolled in the tier's
        // range at game start.
        struct HeroDef
        {
            char const* id;
            uint32_t dbfId;
            int health;
            char const* powerId;
            int armorTier;   // 1..7
            bool curated;    // one of the 18 first heroes
        };
        int HeroCount();
        HeroDef const& HeroAt(int index);
        int FindHero(std::string const& id);
        // The armor range of a tier: 1 -> 0, 2 -> 2-5, ..., 7 -> 7-10. An unknown tier gives 0.
        void ArmorTierRange(int tier, int& lo, int& hi);

        // A quest row (HsBgQuestData.inc, generated from bg.normalized.json and quest_values.json). The
        // `progress` is the {0} of the quest text (the 24.2.0 baseline); `inPool` is the 24.2 offer list.
        // The counting rule is a quest registry entry (HsBgQuests.h) keyed by this id.
        struct QuestDef
        {
            char const* id;
            uint32_t dbfId;
            int progress;
            bool inPool;
        };
        int QuestCount();
        QuestDef const& QuestAt(int index);
        int FindQuest(std::string const& id);

        // A quest reward row (HsBgRewardData.inc, generated). The behaviour is a reward registry entry
        // (HsBgRewards.h) keyed by this id.
        struct RewardDef
        {
            char const* id;
            uint32_t dbfId;
            bool inPool;
        };
        int RewardCount();
        RewardDef const& RewardAt(int index);
        int FindReward(std::string const& id);

        // Queries over the table, in table order. Only fields set in the query are filtered on.
        struct CardQuery
        {
            int minTier = kMinTier;
            int maxTier = kMaxTier;
            uint32_t tribeAny = 0;      // 0 = any tribe; otherwise the card must have one of these (kTribeAll matches all)
            bool pool = true;           // include CardRole::Pool cards
            bool tokens = false;        // include CardRole::Token cards
            bool slice15AOnly = false;
        };
        std::vector<int> QueryCards(CardQuery const& q);
        std::vector<int> CardsOfTier(int tier, bool slice15AOnly = false);        // pool minions only
        std::vector<int> CardsOfTribe(uint32_t tribe, bool slice15AOnly = false); // pool minions only

        // Deterministic random numbers, see the file comment.
        class Rng
        {
        public:
            explicit Rng(uint32_t seed = 1) : m_engine(seed) {}
            uint32_t Next() { return static_cast<uint32_t>(m_engine()); }
            // Uniform integer in [0, bound); bound 0 returns 0.
            uint32_t Uniform(uint32_t bound);
            // Uniform integer in [lo, hi] (inclusive); hi < lo returns lo.
            int Range(int lo, int hi);
            bool Coin() { return (Next() & 1u) != 0; }
            template <class T> void Shuffle(std::vector<T>& v)
            {
                for (std::size_t i = v.size(); i > 1; --i)
                    std::swap(v[i - 1], v[Uniform(static_cast<uint32_t>(i))]);
            }
            std::mt19937& Engine() { return m_engine; }
        private:
            std::mt19937 m_engine;
        };

        // A Magnetic minion merged into a Mech: what it added (kept so a later sell or event log can show it).
        struct Attachment
        {
            int card = -1;
            bool golden = false;
            int attack = 0;
            int health = 0;
            uint32_t keywords = 0;
            int poolCopies = 0;   // pool copies of `card` the attachment holds (returned when the host minion is sold)
        };

        // An extra Deathrattle a minion carries besides its own card's and its Magnetic attachments': the Deathrattle of
        // `card` runs for this minion with the given golden flag (Leapfrogger gives its Deathrattle to a Beast).
        // `kind` names engine effects that have no card of their own; 0 (the default) is a card.
        constexpr int kGrantedCard = 0;
        constexpr int kGrantedSneedLowerTier = 1; // Sneed's Replicator: summon a random minion of a lower Tier
        constexpr int kGrantedStoneElemental = 2; // Bru'kan's Earth Invocation, a 1/1 Elemental
        struct GrantedEffect
        {
            int card = -1;
            bool golden = false;
            int kind = kGrantedCard;
        };

        // A minion in play (shop board, hand or combat). `attack` and `health` are the CURRENT values and already
        // include aura bonuses (auraAttack / auraHealth remember how much of them is an aura, see RecomputeAuras).
        // maxHealth is the health ceiling (base + buffs + aura): combat damage lowers only health.
        struct Minion
        {
            int card = -1;             // card index, -1 = empty
            bool golden = false;
            int attack = 0;
            int health = 0;
            int maxHealth = 0;
            uint32_t keywords = 0;     // own keywords: card, buffs, Magnetic
            uint32_t auraKeywords = 0; // keywords granted by auras this moment (recomputed)
            int auraAttack = 0;        // part of attack / maxHealth that comes from auras (recomputed)
            int auraHealth = 0;
            uint32_t uid = 0;          // stable instance id: assigned by the owner of the minion (shop game); the combat
                                       // renumbers its copies (see HsBgCombat.h) and the event log uses those ids
            uint32_t flags = 0;        // kMinionDestroyed, kMinionFrozen ...
            int poolCopies = 0;        // copies of `card` in the shared pool this minion stands for: 1 for a bought, offered
                                       // or discovered minion, the sum of its three originals for a golden triple, 0 for
                                       // a minion an effect generated. A sold minion returns exactly this many (HsBgPool.h)
            int counters[kMinionCounters] = { 0, 0, 0, 0 };
            int hats = 0;              // Dancin' Deryl: +1/+1 hats on it, passed to a friendly minion when it is sold
            std::vector<Attachment> attachments;
            std::vector<GrantedEffect> granted; // extra Deathrattles (combat only so far, see GrantedEffect)
            uint32_t killer = 0;       // combat: id of the last source that damaged or destroyed this minion (0 = none)
            // "until next turn" spell effects. tempAttack / tempHealth are part of attack / maxHealth and
            // are taken back at the owner's next StartTurn; tempKeywords are the keyword bits the spell granted.
            int tempAttack = 0;
            int tempHealth = 0;
            uint32_t tempKeywords = 0;
            bool temporary = false;       // a Spellcraft spell in hand: it leaves the hand at the owner's next StartTurn
            bool permanentSpell = false;  // Lady Vashj: this spell's effect is permanent
            // Stats this minion got from Blood Gems (Necrolyte steals them back; stats merge on a triple).
            int bloodGemAttack = 0;
            int bloodGemHealth = 0;
            // Gruul Rules. "At the end of your turn, gain +2/+2": a permanent enchantment, carried
            // through combat and merged on a triple.
            bool gruulRules = false;

            uint32_t Keywords() const { return keywords | auraKeywords; }
            bool Has(uint32_t kw) const { return (Keywords() & kw) != 0; }
            CardDef const& Def() const { return CardAt(card); }
            int Tier() const { return card < 0 ? 0 : Def().tier; }
            uint32_t Tribes() const { return card < 0 ? 0u : Def().tribes; }
            bool IsTribe(uint32_t tribe) const { return HasTribe(Tribes(), tribe); }
            // Permanent buff: raises attack, health and maxHealth together.
            void Buff(int dAttack, int dHealth)
            {
                attack += dAttack;
                health += dHealth;
                maxHealth += dHealth;
            }
        };
        constexpr uint32_t kMinionDestroyed = 1u << 0; // marked to die at the next death resolution (poison, Destroy)
        constexpr uint32_t kMinionFrozen = 1u << 1;    // a Frozen tavern offer (kept through the next turn start)
        constexpr uint32_t kMinionTicket = 1u << 2;    // a Darkmoon Ticket on a tavern offer (Silas Darkmoon)

        // A fresh minion of a card: base (or golden) stats and keywords, full health, uid 0.
        Minion MakeMinion(int card, bool golden = false, uint32_t uid = 0);

        // A bounded ordered list of minions (board 7, hand 10). Positions are 0-based from the left.
        template <int Cap> class Slots
        {
        public:
            int Size() const { return static_cast<int>(m_items.size()); }
            bool Empty() const { return m_items.empty(); }
            bool Full() const { return Size() >= Cap; }
            static constexpr int Capacity() { return Cap; }
            Minion& operator[](int i) { return m_items[static_cast<std::size_t>(i)]; }
            Minion const& operator[](int i) const { return m_items[static_cast<std::size_t>(i)]; }
            // Inserts at `pos` (clamped to [0, Size()]); false and nothing changed when full.
            bool Insert(int pos, Minion const& m)
            {
                if (Full())
                    return false;
                if (pos < 0)
                    pos = 0;
                if (pos > Size())
                    pos = Size();
                m_items.insert(m_items.begin() + pos, m);
                return true;
            }
            bool Push(Minion const& m) { return Insert(Size(), m); }
            Minion Remove(int pos)
            {
                Minion m = std::move(m_items[static_cast<std::size_t>(pos)]);
                m_items.erase(m_items.begin() + pos);
                return m;
            }
            void Clear() { m_items.clear(); }
            std::vector<Minion> const& Items() const { return m_items; }
            std::vector<Minion>& Items() { return m_items; }
            // Position of the minion with this uid, or -1.
            int IndexOfUid(uint32_t uid) const
            {
                for (int i = 0; i < Size(); ++i)
                    if (m_items[static_cast<std::size_t>(i)].uid == uid)
                        return i;
                return -1;
            }
        private:
            std::vector<Minion> m_items;
        };
        using Board = Slots<kBoardMax>;
        using Hand = Slots<kHandMax>;
    }
}

#endif
